steps.script:
function transform(ctx) {
  var MAP = { "电信": "telecom", "联通": "unicom", "移动": "cmcc" };
  var isp = (ctx.isp || "").trim();
  var s = isp ? (MAP[isp] !== undefined ? MAP[isp] : (isp.charAt(0) === "@" ? isp.substring(1) : "")) : "";
  var full = (ctx.username || "") + (s ? "@" + s : "");
  var mac = (ctx.local_mac || "").replace(/:/g, "").toLowerCase();
  return { ua: url_encode(full), ep: url_encode(ctx.password || ""), mac: mac };
}
